package io.github.theamethyx.femboyclient.client.scenario;

import java.util.Locale;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.levelgen.structure.BoundingBox;

import io.github.theamethyx.femboyclient.world.GeodeCensus;
import io.github.theamethyx.femboyclient.world.GeodeFixtureBuilder;

/**
 * A geode generated by the vanilla worldgen feature from a fixed seed, with a known number of random
 * ticks applied to its budding blocks. The exact counts are recorded as ground truth when it is
 * built, so the analyzer's output can be checked against them.
 */
public final class GeodeFixtureScenario implements TestScenario {
	/** Space between the scenario origin (floor level) and the bottom of the cleared cube. */
	private static final int LIFT = 4;

	private final String id;
	private final String name;
	private final long seed;
	private final int randomTicks;

	public GeodeFixtureScenario(String id, String name, long seed, int randomTicks) {
		this.id = id;
		this.name = name;
		this.seed = seed;
		this.randomTicks = randomTicks;
	}

	@Override
	public String id() {
		return id;
	}

	@Override
	public String name() {
		return name;
	}

	@Override
	public String description() {
		String exposure = randomTicks == 0 ? "with no growth after generation"
				: String.format(Locale.ROOT, "after %,d random ticks per budding block (about %.1f hours of a loaded chunk at the default random tick speed)",
						randomTicks, GeodeFixtureBuilder.equivalentGameTicks(randomTicks, GeodeFixtureBuilder.DEFAULT_RANDOM_TICK_SPEED) / 20 / 3600);
		return "A vanilla amethyst geode (feature seed " + seed + ") generated inside a " + (GeodeFixtureBuilder.HALF * 2 + 1)
				+ "-block stone cube, " + exposure + ". Its exact block counts are stored as ground truth.";
	}

	@Override
	public BlockPos footprint() {
		int edge = GeodeFixtureBuilder.HALF * 2 + 1;
		return new BlockPos(edge, edge + LIFT, edge);
	}

	public long seed() {
		return seed;
	}

	public int randomTicks() {
		return randomTicks;
	}

	@Override
	public Build build(ServerLevel level, BlockPos origin) {
		BlockPos center = origin.offset(GeodeFixtureBuilder.HALF, LIFT + GeodeFixtureBuilder.HALF, GeodeFixtureBuilder.HALF);
		GeodeFixtureBuilder.Result result = GeodeFixtureBuilder.build(level, center, seed, randomTicks);
		if (!result.placed() || result.census().geodeBounds() == null) {
			throw new IllegalStateException("The geode feature did not place a geode here (it refuses some surroundings); try another spot");
		}

		Build build = new Build();
		build.regions.add(result.cleared());
		build.fixtureRegions.add(new RegionRecord(result.cleared(), name));

		GeodeCensus census = result.census();
		JsonObject truth = build.groundTruth;
		truth.addProperty("kind", "geode_fixture");
		truth.addProperty("seed", seed);
		truth.addProperty("appliedRandomTicksPerBuddingBlock", result.randomTicksApplied());
		truth.addProperty("equivalentGameTicksAtDefaultSpeed", GeodeFixtureBuilder.equivalentGameTicks(result.randomTicksApplied(), GeodeFixtureBuilder.DEFAULT_RANDOM_TICK_SPEED));
		truth.addProperty("method", "vanilla minecraft:amethyst_geode feature placed with the seed, then BlockState.randomTick applied "
				+ "round-robin to every budding amethyst block with a seeded RandomSource");
		JsonObject counts = new JsonObject();
		counts.addProperty("small", census.counts().small());
		counts.addProperty("medium", census.counts().medium());
		counts.addProperty("large", census.counts().large());
		counts.addProperty("cluster", census.counts().cluster());
		truth.add("serverCensus", counts);
		truth.addProperty("buddingBlocks", census.buddingBlocks());
		truth.addProperty("amethystBlocks", census.amethystBlocks());
		truth.addProperty("freeFaces", census.freeFaces());
		truth.addProperty("ownGrowthFaces", census.ownGrowthFaces());
		truth.addProperty("blockedFaces", census.blockedFaces());
		BoundingBox bounds = census.geodeBounds();
		JsonArray box = new JsonArray();
		box.add(bounds.minX());
		box.add(bounds.minY());
		box.add(bounds.minZ());
		box.add(bounds.maxX());
		box.add(bounds.maxY());
		box.add(bounds.maxZ());
		truth.add("geodeBounds", box);

		build.notes.add("Geode with " + census.counts().total() + " growth objects (" + census.counts().cluster() + " clusters) and "
				+ census.buddingBlocks() + " budding blocks.");
		return build;
	}
}
